async function* readArchive(chunks) {
  const iterator = chunks[Symbol.asyncIterator]();
  let sourceDone = false;
  let failed = false;

  try {
    const next = iterator.next;
    const decoder = new TextDecoder("utf-8", { ignoreBOM: true });
    let chunk = null;
    let offset = 0;
    let parts = [];
    let lineNumber = 1;

    while (true) {
      if (chunk === null || offset === chunk.length) {
        const result = await next.call(iterator);

        if (result.done) {
          sourceDone = true;
          parts.push(decoder.decode());
          const line = parts.join("");

          if (line.trim() !== "") {
            yield parseArchiveRecord(line, lineNumber);
          }
          return;
        }

        chunk = result.value;
        offset = 0;
        if (chunk.length === 0) continue;
      }

      const newline = chunk.indexOf(10, offset);
      const end = newline === -1 ? chunk.length : newline;
      const text = decoder.decode(chunk.subarray(offset, end), {
        stream: true
      });

      if (text.length !== 0) parts.push(text);
      offset = newline === -1 ? end : end + 1;

      if (newline !== -1) {
        const line = parts.join("");
        parts = [];
        const currentLine = lineNumber++;

        if (line.trim() !== "") {
          yield parseArchiveRecord(line, currentLine);
        }
      }
    }
  } catch (error) {
    failed = true;
    throw error;
  } finally {
    if (!sourceDone) {
      try {
        const close = iterator.return;
        if (typeof close === "function") {
          await close.call(iterator);
        }
      } catch (error) {
        if (!failed) throw error;
      }
    }
  }
}

function parseArchiveRecord(text, lineNumber) {
  try {
    return JSON.parse(text);
  } catch (error) {
    if (error instanceof SyntaxError) {
      error.code = "INVALID_RECORD";
      error.line = lineNumber;
    }
    throw error;
  }
}
